import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.BBd5PKnH.js";const g="/dev-notes/assets/01-sign-gender-wheel._Z-r-hwr.svg",r="/dev-notes/assets/02-gender-range-table8.CDHpI8uS.svg",p=JSON.parse('{"title":"Giới tính của các hành tinh, Phần 1: Khái niệm, giới tính của sign và thang biểu hiện","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/gender/gender-of-planets-part-1-concepts-signs-and-range.md","filePath":"astro/planets/gender/gender-of-planets-part-1-concepts-signs-and-range.md"}'),o={name:"astro/planets/gender/gender-of-planets-part-1-concepts-signs-and-range.md"};function c(d,n,s,e,u,l){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="gioi-tinh-cua-cac-hanh-tinh-phan-1-khai-niem-gioi-tinh-cua-sign-va-thang-bieu-hien" tabindex="-1">Giới tính của các hành tinh, Phần 1: Khái niệm, giới tính của sign và thang biểu hiện <a class="header-anchor" href="#gioi-tinh-cua-cac-hanh-tinh-phan-1-khai-niem-gioi-tinh-cua-sign-va-thang-bieu-hien" aria-label="Permalink to &quot;Giới tính của các hành tinh, Phần 1: Khái niệm, giới tính của sign và thang biểu hiện&quot;">​</a></h1><p><em>(Demetra George, Ancient Astrology in Theory and Practice, Vol. I, Chương 5 &quot;Gender of the Planets&quot;, Table 7 và Table 8)</em></p><blockquote><p><strong>[Sách]</strong> = dịch và giải nghĩa từ các trang bạn chụp. <strong>[Bổ sung]</strong> = phần mình diễn giải thêm hoặc ghép từ các note trước, nên đối chiếu khi đọc tiếp. Các hình nằm trong thư mục <code>images/</code>. Phần 2 (<code>gender-of-planets-part-2-phase-quadrant-latitude.md</code>) nói về ba điều kiện còn lại: solar phase, góc phần tư và vĩ độ thiên thể. Mình không có công cụ tra cứu. Các tên được nhắc tới (Plato, Ptolemy, Rhetorius, Paulus, Alan White) là những gì sách ghi. Hãy kiểm tra lại trước khi trích dẫn.</p></blockquote><hr><h2 id="tom-tat-nhanh" tabindex="-1">Tóm tắt nhanh <a class="header-anchor" href="#tom-tat-nhanh" aria-label="Permalink to &quot;Tóm tắt nhanh&quot;">​</a></h2><ol><li>Chiêm tinh cổ đại chia hành tinh thành <strong>nam</strong> (Sun, Mercury, Mars, Jupiter, Saturn) và <strong>nữ</strong> (Moon, Venus). Mercury cũng được ghi là <strong>common</strong>.</li><li>&quot;Nam/nữ&quot; ở đây là <strong>hai loại năng lượng</strong>, không chỉ là đàn ông hay phụ nữ: nam = <strong>khởi xướng</strong>, nhanh, đón thay đổi; nữ = <strong>tiếp nhận</strong>, chậm, kháng cự thay đổi.</li><li>Có <strong>4 điều kiện</strong> làm hành tinh nghiêng nam hơn hoặc nữ hơn: <strong>sign, solar phase, góc phần tư, vĩ độ thiên thể</strong>. Sign là điều kiện đầu tiên và quan trọng nhất.</li><li>Hành tinh hoạt động <strong>đúng bản chất</strong> hơn khi điều kiện cùng giới với nó. Điều kiện khác giới thì nó bị <strong>chậm lại</strong> (nếu là nam) hoặc bị <strong>thúc ép</strong> (nếu là nữ).</li><li><strong>Table 8</strong> là một thang 6 mức, giống Table 6 của benefic/malefic: có mức cơ sở rồi điều kiện đẩy sang hai phía.</li><li>Sách cảnh báo: nhiều cách diễn giải cổ (như của Rhetorius) phản ánh <strong>định kiến của thời đó</strong>, đừng áp dụng nguyên văn.</li></ol><hr><h2 id="_1-mo-đau-chuong-5" tabindex="-1">1. Mở đầu chương 5 <a class="header-anchor" href="#_1-mo-đau-chuong-5" aria-label="Permalink to &quot;1. Mở đầu chương 5&quot;">​</a></h2><h3 id="ban-dich" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p><strong>Chiêm tinh cổ đại phân loại các hành tinh theo giới tính nam và nữ.</strong> Sun, Mercury, Mars, Jupiter và Saturn thuộc giới nam; Moon và Venus thuộc giới nữ; Mercury là common (chung). Đây là một trong số ít trường hợp rõ ràng mà giới tính của hành tinh dường như <strong>tương ứng trực tiếp với giới của vị thần cùng tên</strong> (tức thần nam hoặc nữ thần). Tuy nhiên, tồn tại một số điều kiện chiêm tinh khiến một hành tinh, dù giới tính cốt yếu là gì, <strong>dịch chuyển về phía biểu hiện nam tính hoặc nữ tính hơn</strong>.</p><p>Trong ngữ cảnh này, nam và nữ <strong>không chỉ nói về đàn ông và phụ nữ</strong>, mà nói về <strong>hai loại năng lượng cơ bản</strong>. Các triết gia cổ đại như <strong>Plato</strong> định nghĩa năng lượng nam là <strong>khởi xướng hành động</strong> và năng lượng nữ là <strong>tiếp nhận hành động</strong>. <strong>Ptolemy</strong> giải thích việc gán giới tính cho hành tinh bằng các tính chất, trong đó <strong>độ ẩm chủ yếu gắn với nữ và độ khô gắn với nam</strong>. Trong chiêm tinh hiện đại, bạn có thể đã nghe sự phân biệt giới tính được gọi là các cực dương và âm, hoặc yang và yin.</p><p>Lý do là: nếu một hành tinh ở trong <strong>điều kiện nam</strong>, nó sẽ có xu hướng <strong>khởi xướng</strong> hành động. Nếu ở <strong>điều kiện nữ</strong>, nó sẽ có xu hướng là <strong>bên tiếp nhận</strong> hành động. Năng lượng nam đặc trưng bởi <strong>chuyển động nhanh hơn</strong> và chào đón thay đổi, nên các sự kiện của hành tinh trong điều kiện nam <strong>xảy ra sớm hơn</strong>. Năng lượng nữ chuyển động <strong>chậm hơn</strong>, kháng cự thay đổi, nên kết quả của hành tinh trong điều kiện nữ <strong>đến muộn hơn</strong>. Phần lớn, hành tinh nam hành động đúng bản chất cơ bản hơn khi ở điều kiện nam, và hành tinh nữ cũng vậy khi ở điều kiện nữ.</p></blockquote><h3 id="phan-tich" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><p><strong>a) Giới tính cơ bản của 7 hành tinh</strong> [Sách]:</p><table tabindex="0"><thead><tr><th>Giới</th><th>Hành tinh</th></tr></thead><tbody><tr><td>Nam (masculine)</td><td>Sun, Mars, Jupiter, Saturn, và Mercury (xếp vào nhóm nam ở Table 7)</td></tr><tr><td>Nữ (feminine)</td><td>Moon, Venus</td></tr></tbody></table><p><strong>Cập nhật quan trọng về Mercury</strong> [Bổ sung]: ở Table 5 (note trước), Mercury được ghi là &quot;androgynous&quot; (lưỡng tính) và không nằm trong nhóm nam. Ở chương 5, Table 7 xếp Mercury vào <strong>nhóm nam</strong>, còn câu văn ghi &quot;Mercury là common&quot;. Cách hợp lý nhất để hiểu hai nơi: Mercury <strong>mặc định xếp nam nhưng linh hoạt</strong>, dễ nghiêng về hai phía hơn các hành tinh khác. Mình đã cập nhật hai note cũ cho khớp.</p><p><strong>b) Giới tính khớp với thần cùng tên</strong> [Sách, thêm chi tiết từ Table 3]:</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Thần</th><th>Giới của thần</th></tr></thead><tbody><tr><td>Sun</td><td>Hēlios, Apollō</td><td>Nam</td></tr><tr><td>Moon</td><td>Selēnē, Artemis, Hekatē</td><td>Nữ</td></tr><tr><td>Mercury</td><td>Hermēs</td><td>Nam</td></tr><tr><td>Venus</td><td>Aphroditē</td><td>Nữ</td></tr><tr><td>Mars</td><td>Arēs</td><td>Nam</td></tr><tr><td>Jupiter</td><td>Zeus</td><td>Nam</td></tr><tr><td>Saturn</td><td>Kronos</td><td>Nam</td></tr></tbody></table><p>Sách nói đây là &quot;một trong số ít trường hợp rõ ràng&quot;: hầu hết các phân loại khác (benefic/malefic, sect, nóng/lạnh) không khớp trực tiếp với thần thoại như vậy.</p><p><strong>c) &quot;Giới tính&quot; ở đây là loại năng lượng, không phải giới của con người</strong> [Sách, giải nghĩa thêm]. Ba cách nói cùng một ý:</p><table tabindex="0"><thead><tr><th>Nguồn</th><th>Nam</th><th>Nữ</th></tr></thead><tbody><tr><td>Plato</td><td>Khởi xướng hành động</td><td>Tiếp nhận hành động</td></tr><tr><td>Ptolemy (qua tính chất)</td><td>Khô</td><td>Ẩm</td></tr><tr><td>Chiêm tinh hiện đại</td><td>Dương (yang), cực dương</td><td>Âm (yin), cực âm</td></tr></tbody></table><p>Cho nên một hành tinh &quot;nữ&quot; không có nghĩa là liên quan đến phụ nữ, và hành tinh &quot;nam&quot; không chỉ liên quan đến đàn ông.</p><p><strong>d) Cơ chế: nhanh hay chậm, sớm hay muộn</strong> [Sách]:</p><table tabindex="0"><thead><tr><th></th><th>Điều kiện nam</th><th>Điều kiện nữ</th></tr></thead><tbody><tr><td>Vai trò</td><td>Khởi xướng</td><td>Tiếp nhận</td></tr><tr><td>Nhịp độ</td><td>Nhanh hơn</td><td>Chậm hơn</td></tr><tr><td>Với thay đổi</td><td>Chào đón</td><td>Kháng cự</td></tr><tr><td>Sự kiện</td><td>Xảy ra <strong>sớm</strong> hơn</td><td>Đến <strong>muộn</strong> hơn</td></tr></tbody></table><p><strong>e) Quy tắc ẩm và khô của Ptolemy có một ngoại lệ: Jupiter</strong> [Bổ sung, mình ghép từ Table 5]:</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Ẩm hay khô (Table 5)</th><th>Theo quy tắc &quot;ẩm = nữ, khô = nam&quot;</th><th>Giới thực tế</th></tr></thead><tbody><tr><td>Moon</td><td>Ẩm</td><td>Nữ</td><td>Nữ (khớp)</td></tr><tr><td>Venus</td><td>Ẩm</td><td>Nữ</td><td>Nữ (khớp)</td></tr><tr><td>Sun</td><td>Khô</td><td>Nam</td><td>Nam (khớp)</td></tr><tr><td>Mars</td><td>Khô</td><td>Nam</td><td>Nam (khớp)</td></tr><tr><td>Saturn</td><td>Khô</td><td>Nam</td><td>Nam (khớp)</td></tr><tr><td><strong>Jupiter</strong></td><td><strong>Ẩm</strong></td><td><strong>Nữ</strong></td><td><strong>Nam (ngoại lệ)</strong></td></tr><tr><td>Mercury</td><td>Thay đổi</td><td>Thay đổi</td><td>Nam (thay đổi)</td></tr></tbody></table><p>Jupiter vừa ấm vừa ẩm nhưng lại là hành tinh nam. Sách chưa giải thích trong các trang này. Cách mình đọc (suy đoán): giới tính ở đây không chỉ dựa vào tính chất mà còn khớp với thần cùng tên (Zeus là nam) và phe ngày.</p><p><strong>f) Giới tính và phe không trùng nhau</strong> [Bổ sung, nhắc lại note trước]:</p><table tabindex="0"><thead><tr><th></th><th>Phe ngày</th><th>Phe đêm</th></tr></thead><tbody><tr><td>Nam</td><td>Sun, Jupiter, Saturn</td><td><strong>Mars</strong></td></tr><tr><td>Nữ</td><td>(không có)</td><td>Moon, Venus</td></tr></tbody></table><p>Mars là hành tinh nam duy nhất thuộc phe đêm.</p><p><strong>g) Một chỗ có vẻ mâu thuẫn: Saturn nam nhưng chậm nhất</strong> [Bổ sung]. Sách mô tả năng lượng nam là nhanh và chào đón thay đổi, trong khi Saturn là hành tinh nam nhưng mô tả của nó (note trước) lại gắn với trì hoãn, giới hạn, kéo dài. Điều này cho thấy &quot;nhanh, chậm&quot; ở đây là <strong>phong cách năng lượng</strong> (chủ động khởi xướng hay đợi tiếp nhận), không phải tốc độ quỹ đạo thật. Sách không bàn thẳng chỗ này trong các trang đã gửi.</p><p><strong>h) Gợi ý dùng để đoán thời điểm</strong> [Bổ sung, mở rộng từ đoạn &quot;sớm hơn, muộn hơn&quot;]: sách nói sự kiện của hành tinh trong điều kiện nam xảy ra sớm hơn, điều kiện nữ muộn hơn. Có thể dùng để <strong>ước lượng nhịp độ</strong>: chủ đề do hành tinh nam hóa cai quản thì &quot;tiến nhanh&quot;, chủ đề do hành tinh nữ hóa cai quản thì &quot;chín muộn&quot;. Sách chưa dạy cách dùng này cụ thể, nên coi đây là hướng gợi ý, chưa phải kỹ thuật chính thức.</p><hr><h2 id="_2-bon-đieu-kien-đoi-gioi-tinh-table-7" tabindex="-1">2. Bốn điều kiện đổi giới tính (Table 7) <a class="header-anchor" href="#_2-bon-đieu-kien-đoi-gioi-tinh-table-7" aria-label="Permalink to &quot;2. Bốn điều kiện đổi giới tính (Table 7)&quot;">​</a></h2><h3 id="ban-dich-1" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich-1" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p>Các hành tinh được điều chỉnh để trở nên <strong>nam hơn</strong> hoặc <strong>nữ hơn</strong> bởi các điều kiện sau: (1) <strong>Sign hoàng đạo</strong>, (2) <strong>Solar phase</strong>, (3) <strong>Vĩ độ thiên thể</strong>, (4) <strong>Vị trí góc phần tư</strong>.</p></blockquote><h3 id="table-7-gioi-tinh-cua-hanh-tinh" tabindex="-1">Table 7: Giới tính của hành tinh <a class="header-anchor" href="#table-7-gioi-tinh-cua-hanh-tinh" aria-label="Permalink to &quot;Table 7: Giới tính của hành tinh&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><strong>Nam hóa</strong> (masculinizing)</th><th><strong>Nữ hóa</strong> (feminizing)</th></tr></thead><tbody><tr><td>Hành tinh gốc</td><td><strong>Nam:</strong> Sun, Mercury, Mars, Jupiter, Saturn</td><td><strong>Nữ:</strong> Moon, Venus</td></tr><tr><td><strong>1. Sign</strong></td><td>Aries, Gemini, Leo, Libra, Sagittarius, Aquarius</td><td>Taurus, Cancer, Virgo, Scorpio, Capricorn, Pisces</td></tr><tr><td><strong>2. Phase</strong></td><td>Buổi sáng, đi trước Sun</td><td>Buổi chiều, đi sau Sun</td></tr><tr><td><strong>3. Quadrant</strong></td><td>Asc đến MC; Dsc đến IC</td><td>MC đến Dsc; IC đến Asc</td></tr><tr><td><strong>4. Latitude</strong></td><td>Bắc</td><td>Nam</td></tr></tbody></table><h3 id="phan-tich-1" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich-1" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><ul><li><strong>Thứ tự</strong>: danh sách đánh số của sách là sign, phase, latitude, quadrant, nhưng bảng xếp sign, phase, quadrant, latitude. Phần văn bản ở chương cũng bàn theo thứ tự sign, phase, quadrant, latitude. Phần 2 đi theo thứ tự này.</li><li><strong>Bốn điều kiện không bằng nhau</strong>: sách nói giới tính của sign là yếu tố <strong>đầu tiên và quan trọng nhất</strong>.</li><li><strong>Cách nhớ</strong> [Bổ sung]: hướng &quot;nam hóa&quot; gắn với những gì <strong>chủ động, đang lên, buổi sáng, phía bắc</strong>; hướng &quot;nữ hóa&quot; gắn với những gì <strong>tiếp nhận, đang xuống, buổi chiều, phía nam</strong>. Phần 2 giải thích vì sao.</li></ul><hr><h2 id="_3-gioi-tinh-cua-sign-đieu-kien-so-1" tabindex="-1">3. Giới tính của sign (điều kiện số 1) <a class="header-anchor" href="#_3-gioi-tinh-cua-sign-đieu-kien-so-1" aria-label="Permalink to &quot;3. Giới tính của sign (điều kiện số 1)&quot;">​</a></h2><h3 id="ban-dich-2" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich-2" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p><strong>Giới tính của sign hoàng đạo</strong> mà hành tinh đang đứng là yếu tố <strong>đầu tiên và quan trọng nhất</strong> trong việc đánh giá này. Các sign nam là Aries, Gemini, Leo, Libra, Sagittarius và Aquarius, tương ứng với nguyên tố <strong>lửa và khí</strong>. Các sign nữ là Taurus, Cancer, Virgo, Scorpio, Capricorn và Pisces, thuộc nguyên tố <strong>đất và nước</strong>. Hành tinh nam hành động đúng với bản chất cốt yếu của nó hơn khi ở sign nam, còn hành tinh nữ hành động đúng với bản chất cơ bản hơn khi ở sign nữ.</p><p>Cũng như việc làm chính mình và làm tốt nhất sẽ dễ hơn khi ta ở trong một môi trường nâng đỡ và củng cố bản chất của mình, các hành tinh cũng hoạt động tốt hơn trong các sign có <strong>nhịp độ giống nhịp độ của chúng</strong>. Khi một hành tinh nam ở sign nữ, khả năng hành động của nó <strong>bị chậm lại</strong>, có thể là nguồn của sự bực bội hoặc chán nản. Nếu một hành tinh nữ ở sign nam, nó có thể cảm thấy <strong>bị thúc ép phải hành động trước khi sẵn sàng</strong>, và vì thế trở thành nguồn căng thẳng. Alan White quá cố từng minh họa nguyên lý này bằng ví dụ một cặp đôi tuổi teen ở rạp chiếu phim ngoài trời, một bên muốn mọi thứ nhanh lên trong khi bên kia muốn chậm lại.</p><p>Nói chung, condition của hành tinh được cải thiện khi nó ở sign cùng giới, nhưng <strong>đây không phải quy tắc tuyệt đối</strong>. Không có phán xét giá trị giữa nhanh và kéo dài, giữa nở sớm và nở muộn; bối cảnh của từng tình huống quyết định loại năng lượng nào có lợi hơn. Và đôi khi điều tốt nhất là để cái nhanh chậm lại, như tốc độ viêm của một căn bệnh.</p></blockquote><h3 id="hinh-12-sign-nam-va-nu-xen-ke" tabindex="-1">Hình: 12 sign nam và nữ xen kẽ <a class="header-anchor" href="#hinh-12-sign-nam-va-nu-xen-ke" aria-label="Permalink to &quot;Hình: 12 sign nam và nữ xen kẽ&quot;">​</a></h3><p><img src="'+g+'" alt="Giới tính của 12 sign"></p><h3 id="phan-tich-2" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich-2" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><p><strong>a) Bảng tóm tắt hành tinh và sign</strong> [Sách]:</p><table tabindex="0"><thead><tr><th></th><th>Ở sign nam (lửa, khí)</th><th>Ở sign nữ (đất, nước)</th></tr></thead><tbody><tr><td><strong>Hành tinh nam</strong></td><td>Hợp nhịp, hành động đúng bản chất</td><td><strong>Bị chậm lại</strong>, dễ bực bội hoặc chán</td></tr><tr><td><strong>Hành tinh nữ</strong></td><td><strong>Bị thúc ép</strong>, phải hành động trước khi sẵn sàng, căng thẳng</td><td>Hợp nhịp, hành động đúng bản chất</td></tr></tbody></table><p><strong>b) Sign nam và nữ xen kẽ</strong>: bắt đầu từ Aries (nam), Taurus (nữ), Gemini (nam), Cancer (nữ)... Cứ cách một sign đổi giới. Nên dễ nhớ: số thứ tự lẻ (Aries là 1, Gemini là 3, Leo là 5...) là nam, số chẵn là nữ.</p><p><strong>c) Giới tính sign gắn với nguyên tố</strong> [Sách]: lửa và khí là nam, đất và nước là nữ. Liên hệ với bài tính chất nguyên tố [Bổ sung]: lửa (nóng-khô) và khí (nóng-ẩm) đều <strong>có phần nóng</strong>, đất (lạnh-khô) và nước (lạnh-ẩm) đều <strong>có phần lạnh</strong>. Vì vậy sign nam là sign nóng hơn, sign nữ là sign lạnh hơn. Đây là liên hệ của mình, sách chưa nêu trong các trang này.</p><p><strong>d) Mỗi hành tinh có ít nhất một domicile cùng giới</strong> [Bổ sung, ghép Figure 3 rulerships với Table 7]:</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Giới</th><th>Domicile 1</th><th>Domicile 2</th></tr></thead><tbody><tr><td>Sun</td><td>Nam</td><td>Leo (nam, hợp)</td><td></td></tr><tr><td>Moon</td><td>Nữ</td><td>Cancer (nữ, hợp)</td><td></td></tr><tr><td>Mercury</td><td>Nam</td><td>Gemini (nam, hợp)</td><td>Virgo (nữ, <strong>lệch</strong>)</td></tr><tr><td>Venus</td><td>Nữ</td><td>Taurus (nữ, hợp)</td><td>Libra (nam, <strong>lệch</strong>)</td></tr><tr><td>Mars</td><td>Nam</td><td>Aries (nam, hợp)</td><td>Scorpio (nữ, <strong>lệch</strong>)</td></tr><tr><td>Jupiter</td><td>Nam</td><td>Sagittarius (nam, hợp)</td><td>Pisces (nữ, <strong>lệch</strong>)</td></tr><tr><td>Saturn</td><td>Nam</td><td>Aquarius (nam, hợp)</td><td>Capricorn (nữ, <strong>lệch</strong>)</td></tr></tbody></table><p>Ý nghĩa: ở domicile, hành tinh có dignity nhưng <strong>giới tính của sign có thể lệch</strong> với giới của hành tinh. Ví dụ Saturn ở Capricorn (domicile) vẫn đang ở sign nữ (đất), nên &quot;được ở nhà&quot; nhưng nhịp độ bị chậm lại. Dignity và giới tính là <strong>hai lớp đánh giá độc lập</strong>.</p><p><strong>e) &quot;Không phải quy tắc tuyệt đối&quot;</strong> [Sách]: sách nhấn mạnh <strong>không có phán xét giá trị</strong> giữa nhanh và chậm. Ví dụ y học: với một cơn viêm, điều tốt nhất là để tiến trình nhanh chậm lại. Nên hành tinh nam ở sign nữ không nhất thiết là xấu: tùy bối cảnh, &quot;chậm lại&quot; có thể có lợi.</p><p><strong>f) Hai cảm giác khác nhau</strong> [Sách, tóm lại]:</p><ul><li>Hành tinh nam ở sign nữ → <strong>bực bội, chán</strong> (muốn đi mà bị kéo lại).</li><li>Hành tinh nữ ở sign nam → <strong>căng thẳng, vội</strong> (chưa sẵn sàng mà bị đẩy).</li></ul><hr><h2 id="_4-thang-bieu-hien-nu-hoa-va-nam-hoa-table-8" tabindex="-1">4. Thang biểu hiện nữ hóa và nam hóa (Table 8) <a class="header-anchor" href="#_4-thang-bieu-hien-nu-hoa-va-nam-hoa-table-8" aria-label="Permalink to &quot;4. Thang biểu hiện nữ hóa và nam hóa (Table 8)&quot;">​</a></h2><h3 id="ban-dich-3" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich-3" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p>Tương tự bản chất benefic hay malefic cơ bản của hành tinh, <strong>giới tính nam hay nữ của hành tinh cũng có thể được điều chỉnh</strong> theo nhiều cách ảnh hưởng đến biểu hiện của nó.</p></blockquote><p><strong>Table 8: Phạm vi biểu hiện nữ hóa và nam hóa của hành tinh</strong></p><table tabindex="0"><thead><tr><th></th><th>← Điều kiện nữ</th><th>Điều kiện trung tính</th><th>Điều kiện nam →</th></tr></thead><tbody><tr><td><strong>Hành tinh nữ</strong></td><td>Cực kỳ nữ tính</td><td>Nữ tính</td><td>Nữ tính bị nam hóa</td></tr><tr><td><strong>Hành tinh nam</strong></td><td>Nam tính bị nữ hóa</td><td>Nam tính</td><td>Cực kỳ nam tính</td></tr></tbody></table><blockquote><p><strong>Rhetorius</strong>, bị định hình bởi các chuẩn mực văn hóa thời ông, kết luận rằng các hành tinh nam trong điều kiện nam khiến đàn ông bướng bỉnh và táo bạo, nhưng khiến phụ nữ ngỗ ngược và vô liêm sỉ. Tương tự, các hành tinh nữ trong điều kiện nữ khiến đàn ông mềm yếu và hèn nhát, còn phụ nữ khiêm tốn, đoan trang và ngoan ngoãn. Tuy nhiên, hãy nhớ rằng <strong>nhiều cách diễn giải biểu tượng không tránh khỏi phản ánh phong tục và giá trị của thời đó</strong>. Trong thế giới đương đại, các điều chỉnh giới của hành tinh có thể đem lại những cái nhìn quý giá về cách biểu hiện của sự linh hoạt giới tính (gender fluidity), ví dụ trong cộng đồng LGBTQIA.</p></blockquote><h3 id="hinh-table-8-ve-lai-va-đat-tren-mot-thang" tabindex="-1">Hình: Table 8 vẽ lại và đặt trên một thang <a class="header-anchor" href="#hinh-table-8-ve-lai-va-đat-tren-mot-thang" aria-label="Permalink to &quot;Hình: Table 8 vẽ lại và đặt trên một thang&quot;">​</a></h3><p><img src="'+r+'" alt="Table 8 và thang nữ đến nam"></p><h3 id="phan-tich-3" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich-3" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><p><strong>a) Cách đọc bảng</strong>: hàng là hành tinh (nữ hay nam), cột là điều kiện (nữ, trung tính, nam). Ô ở giữa là mức cơ sở. Đi sang cùng phía với giới của hành tinh thì <strong>cực đoan hơn</strong>. Đi sang phía ngược lại thì <strong>pha trộn</strong>.</p><p><strong>b) Tên gọi cho thấy hành tinh vẫn giữ giới gốc</strong> [Bổ sung]: &quot;nữ tính bị nam hóa&quot; vẫn là hành tinh <strong>nữ</strong> (chỉ nghiêng nam), &quot;nam tính bị nữ hóa&quot; vẫn là hành tinh <strong>nam</strong> (chỉ nghiêng nữ). Giống Table 6 ở note trước: điều kiện dịch chuyển biểu hiện nhưng không đổi hẳn loại.</p><p><strong>c) So sánh Table 6 và Table 8</strong> [Bổ sung]:</p><table tabindex="0"><thead><tr><th></th><th>Table 6 (benefic/malefic)</th><th>Table 8 (nam/nữ)</th></tr></thead><tbody><tr><td>Mức cơ sở</td><td>Benefic = tốt, malefic = xấu</td><td>Hành tinh nam = nam tính, nữ = nữ tính</td></tr><tr><td>Yếu tố điều chỉnh</td><td>Sect, dignity, phase, aspect, house</td><td>Sign, phase, quadrant, latitude</td></tr><tr><td>Số bậc</td><td>5</td><td>3 cột cho mỗi hàng</td></tr><tr><td>Có đổi hẳn loại không?</td><td>Không</td><td>Không</td></tr></tbody></table><p>Câu mở đầu của sách (&quot;tương tự bản chất benefic/malefic&quot;) cho thấy cùng một <strong>mô hình tư duy</strong>: hành tinh có bản chất gốc, và nhiều điều kiện khiến biểu hiện của nó đi lên hay xuống.</p><p><strong>d) Về phần Rhetorius</strong>: các kết luận của ông gắn với <strong>vai trò giới truyền thống</strong> (đàn ông phải táo bạo, phụ nữ phải đoan trang, ngoan ngoãn). Chính tác giả nói đây là sản phẩm của chuẩn mực thời đó. Cách dùng phù hợp ngày nay:</p><ul><li>Dịch lại thành <strong>phong cách năng lượng</strong>, không gắn với giới tính của người đó: nam hóa là <strong>chủ động, nhanh, khởi xướng</strong>; nữ hóa là <strong>thong thả, tiếp nhận, chín muộn</strong>.</li><li>Cách sách gợi ý: các điều chỉnh này có thể giúp hiểu <strong>sự linh hoạt giới tính (gender fluidity)</strong> của một người. Đây là hướng mở của tác giả, bạn chỉ nên dùng khi người đối diện chủ động chia sẻ, đừng tự suy ra.</li></ul><hr><h2 id="_5-ap-dung-so-bo-gioi-tinh-cua-sign-trong-la-so-mau-bo-sung" tabindex="-1">5. Áp dụng sơ bộ: giới tính của sign trong lá số mẫu [Bổ sung] <a class="header-anchor" href="#_5-ap-dung-so-bo-gioi-tinh-cua-sign-trong-la-so-mau-bo-sung" aria-label="Permalink to &quot;5. Áp dụng sơ bộ: giới tính của sign trong lá số mẫu [Bổ sung]&quot;">​</a></h2><p>(Các điều kiện còn lại tính ở Phần 2.)</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Giới gốc</th><th>Sign</th><th>Giới của sign</th><th>Kết quả theo sách</th></tr></thead><tbody><tr><td>Sun</td><td>Nam</td><td>Aquarius</td><td>Nam</td><td>Hợp nhịp</td></tr><tr><td>Moon</td><td>Nữ</td><td>Libra</td><td>Nam</td><td><strong>Bị thúc ép</strong></td></tr><tr><td>Mercury</td><td>Nam</td><td>Capricorn</td><td>Nữ</td><td><strong>Bị chậm lại</strong></td></tr><tr><td>Venus</td><td>Nữ</td><td>Sagittarius</td><td>Nam</td><td><strong>Bị thúc ép</strong></td></tr><tr><td>Mars</td><td>Nam</td><td>Sagittarius</td><td>Nam</td><td>Hợp nhịp</td></tr><tr><td>Jupiter</td><td>Nam</td><td>Leo</td><td>Nam</td><td>Hợp nhịp</td></tr><tr><td>Saturn</td><td>Nam</td><td>Gemini</td><td>Nam</td><td>Hợp nhịp</td></tr></tbody></table><p><strong>Nhận xét:</strong> bốn hành tinh nam trong sign nam đều hợp nhịp. Hai hành tinh nữ (Moon, Venus) đều ở sign nam, nên bị nam hóa. Mercury là hành tinh duy nhất bị làm chậm lại.</p><hr><h2 id="_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">6. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;6. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><ul><li>Dùng ngôn ngữ <strong>năng lượng</strong> thay vì giới tính của con người: &quot;chủ động, đẩy nhanh&quot; hay &quot;thong thả, chờ chín&quot;, không nói &quot;kiểu đàn ông&quot; hoặc &quot;kiểu phụ nữ&quot;.</li><li><strong>Đừng dùng nguyên văn các kết luận của Rhetorius</strong> (ví dụ về đàn ông mềm yếu, phụ nữ ngỗ ngược). Sách đã cảnh báo đây là định kiến của thời đó.</li><li><strong>Đừng giả định giới của người đối diện</strong> từ lá số. Hành tinh nam hay nữ không nói người đó là nam hay nữ, hay họ nên hành xử thế nào.</li><li>Với hành tinh nữ ở sign nam: có thể nói &quot;bạn có thể thấy mình bị thúc phải quyết nhanh trước khi sẵn sàng&quot;. Với hành tinh nam ở sign nữ: &quot;bạn có thể thấy khó chịu vì mọi việc diễn ra chậm hơn mong muốn&quot;.</li><li>Nhớ tinh thần note_5: lá số mô tả <strong>hoàn cảnh và xu hướng</strong>, không áp đặt cách sống của một người.</li></ul><hr><h2 id="_7-tu-kiem-tra" tabindex="-1">7. Tự kiểm tra <a class="header-anchor" href="#_7-tu-kiem-tra" aria-label="Permalink to &quot;7. Tự kiểm tra&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Câu hỏi</th><th>Đáp án</th></tr></thead><tbody><tr><td>Hành tinh nữ là những hành tinh nào?</td><td>Moon, Venus</td></tr><tr><td>&quot;Nam/nữ&quot; ở đây chủ yếu chỉ điều gì?</td><td>Hai loại năng lượng: khởi xướng và tiếp nhận</td></tr><tr><td>Ptolemy gắn ẩm và khô với giới nào?</td><td>Ẩm với nữ, khô với nam</td></tr><tr><td>Sign nam gồm những sign nào?</td><td>Aries, Gemini, Leo, Libra, Sagittarius, Aquarius (lửa và khí)</td></tr><tr><td>Hành tinh nam ở sign nữ thì thế nào?</td><td>Bị chậm lại, dễ bực bội hoặc chán</td></tr><tr><td>Hành tinh nữ ở sign nam thì thế nào?</td><td>Bị thúc ép, căng thẳng</td></tr><tr><td>Điều kiện nào quan trọng nhất trong bốn điều kiện?</td><td>Giới tính của sign</td></tr><tr><td>&quot;Nữ tính bị nam hóa&quot; là hành tinh gì?</td><td>Hành tinh nữ ở điều kiện nam (vẫn là hành tinh nữ)</td></tr><tr><td>Vì sao sách cảnh báo về Rhetorius?</td><td>Cách diễn giải phản ánh chuẩn mực văn hóa thời ông</td></tr></tbody></table><hr><h2 id="_8-tu-vung-kho" tabindex="-1">8. Từ vựng khó <a class="header-anchor" href="#_8-tu-vung-kho" aria-label="Permalink to &quot;8. Từ vựng khó&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiếng Anh</th><th>Tiếng Việt</th></tr></thead><tbody><tr><td>Masculine / feminine</td><td>Nam / nữ (loại năng lượng)</td></tr><tr><td>Androgynous</td><td>Lưỡng tính</td></tr><tr><td>Initiate / receive (action)</td><td>Khởi xướng / tiếp nhận (hành động)</td></tr><tr><td>Polarity</td><td>Cực (dương, âm)</td></tr><tr><td>Masculinize / feminize</td><td>Nam hóa / nữ hóa</td></tr><tr><td>Willful</td><td>Bướng bỉnh, ngang ngạnh</td></tr><tr><td>Insubordinate</td><td>Không phục tùng, ngỗ ngược</td></tr><tr><td>Shameless</td><td>Vô liêm sỉ</td></tr><tr><td>Gender fluidity</td><td>Sự linh hoạt giới tính</td></tr><tr><td>Pace</td><td>Nhịp độ</td></tr></tbody></table><hr><h2 id="_9-đieu-can-kiem-chung" tabindex="-1">9. Điều cần kiểm chứng <a class="header-anchor" href="#_9-đieu-can-kiem-chung" aria-label="Permalink to &quot;9. Điều cần kiểm chứng&quot;">​</a></h2><ul><li>Bản dịch dựa trên các trang bạn chụp. Phần ví dụ của Alan White mình diễn đạt lại ngắn gọn, trung tính.</li><li>Mercury: Table 5 ghi &quot;androgynous&quot;, Table 7 xếp vào nhóm nam, văn bản ghi &quot;common&quot;. Mình hiểu là &quot;mặc định nam nhưng linh hoạt&quot;, sách chưa giải thích trực tiếp.</li><li>Các mục e, g, h của phần 1, mục c, d của phần 3, và phần 5 là cách mình đọc thêm, không phải lập luận tác giả nêu rõ.</li><li>Ngoại lệ Jupiter (ẩm nhưng là nam) và việc Saturn là hành tinh nam dù chậm nhất: sách chưa giải thích trong các trang này.</li></ul>',89)])])}const b=t(o,[["render",c]]);export{p as __pageData,b as default};
